<script lang="ts">
 import {onDestroy,untrack} from 'svelte';
 import type {FieldDefinition,RecordPage} from '../api/domain';
 import type {ModuleView} from '../api/moduleViews';
 import {listRecords} from '../api/workspace';
 import {loadWorkflow,loadWorkQueue,type WorkQueue, type WorkflowConfiguration} from '../api/workflows';
 import {summaryValue,summaryNames} from '../util/columnSummaries';
 import {recordFieldText} from '../util/moduleViews';
 let {moduleUid,view,fields,revision=0,onOpen}:{moduleUid:string;view:ModuleView;fields:FieldDefinition[];revision?:number;onOpen:(uid:string)=>void}=$props();
 let data=$state<RecordPage|null>(null);let workflow=$state<WorkflowConfiguration|null>(null);let tasks=$state<WorkQueue|null>(null);let stages=$state<{name:string;total:number}[]>([]);let loading=$state(true);let error=$state('');let controller:AbortController|undefined;let generation=0;let dead=false;
 $effect(()=>{moduleUid;view.id;revision;untrack(()=>void reload());});onDestroy(()=>{dead=true;generation++;controller?.abort();});
 async function reload(){controller?.abort();const request=new AbortController();controller=request;const current=++generation;loading=true;error='';try{
  const [records,process]=await Promise.all([listRecords({limit:6},moduleUid,request.signal),loadWorkflow(moduleUid,request.signal)]);if(dead||current!==generation)return;data=records;workflow=process;tasks=null;stages=[];
  if(process.definition.enabled){const [todo,counts]=await Promise.all([loadWorkQueue(moduleUid,{actionable:true,include_total:true},request.signal),loadWorkQueue(moduleUid,{counts_only:true},request.signal)]);if(dead||current!==generation)return;tasks=todo;
   stages=process.definition.states.map(s=>({name:s.name,total:counts.stage_totals?.find(n=>n.state===s.key)?.total||0}));
  }
 }catch(e){if(!request.signal.aborted&&!dead)error=e instanceof Error?e.message:String(e);}finally{if(current===generation)loading=false;}}
 const summaries=$derived(view.summary_fields.map(key=>fields.find(f=>f.key===key)).filter((f):f is FieldDefinition=>!!f));
</script>
<div class="overview-heading"><div><h2>{view.name}</h2><p>Current information you have permission to view.</p></div><button class="button" disabled={loading} onclick={reload}>Refresh overview</button></div>
{#if error}<p class="notice error" role="alert">{error}</p>{/if}
<div class="metric-grid" aria-busy={loading}><article><span>Total records</span><strong>{data?.total.toLocaleString()??'…'}</strong><small>Across this module</small></article>{#if workflow?.definition.enabled}<article><span>Needs my action</span><strong>{tasks?.total?.toLocaleString()??'…'}</strong><small>Permitted process actions</small></article>{/if}{#each summaries as field}<article><span>{field.label}</span><strong>{data?summaryValue(data.summaries?.[field.key]):'…'}</strong><small>{summaryNames[field.config.table_summary as keyof typeof summaryNames]} · all visible records</small></article>{/each}</div>
{#if stages.length}<section class="stage-overview" aria-label="Process stage totals"><h3>{workflow?.definition.name}</h3><div>{#each stages as stage}<article><span>{stage.name}</span><strong>{stage.total.toLocaleString()}</strong></article>{/each}</div></section>{/if}
<div class="operations-grid">{#if workflow?.definition.enabled}<section class="operation-panel"><header><h3>Action inbox</h3><span>{tasks?.total??0} items</span></header><p class="muted">Review a saved item before making a decision.</p>{#each tasks?.items.slice(0,8)||[] as item}<button class="task-row" onclick={()=>onOpen(item.uid)}><span><strong>{item.title}</strong><small>{item.state_name}</small></span><span class="task-action">{item.actions?.map(a=>a.name).join(' / ')||'Review'} →</span></button>{/each}{#if !loading&&!tasks?.items.length}<p class="empty-state compact">No items need your action.</p>{/if}{#if tasks?.has_next}<p class="muted">Showing the first eight items. Use the pipeline view for the complete queue.</p>{/if}</section>{/if}
<section class="operation-panel"><header><h3>Record register</h3><span>Quick access</span></header><p class="muted">The first six records in the module’s default order.</p>{#each data?.data||[] as record}<button class="task-row" onclick={()=>onOpen(record.uid)}><span><strong>{recordFieldText(record,view.title_field||fields.find(f=>f.field_type!=='attachments')?.key||'',fields)}</strong>{#if view.fields[0]}<small>{recordFieldText(record,view.fields[0],fields)}</small>{/if}</span><span aria-hidden="true">→</span></button>{/each}{#if !loading&&!data?.data.length}<p class="empty-state compact">No records yet. Add your first entry above.</p>{/if}</section></div>
{#if loading}<p role="status">Loading current overview…</p>{/if}
<style>
 .overview-heading{display:flex;justify-content:space-between;align-items:center;gap:.75rem;margin-bottom:.75rem;flex-wrap:wrap}.overview-heading h2{margin:0;font-size:.9375rem;font-weight:650}.overview-heading p{margin:.2rem 0 0;color:var(--muted);font-size:.75rem}
 .metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,12rem),1fr));gap:.75rem}.metric-grid article{padding:.85rem 1rem;border:1px solid var(--line);border-radius:var(--card-radius);background:var(--surface);display:grid;gap:.3rem}.metric-grid span{font-size:.8125rem;color:var(--muted)}.metric-grid strong{font-size:1.65rem;font-weight:600;line-height:1.2;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.metric-grid small{font-size:.75rem;color:var(--muted)}
 .stage-overview{padding:.85rem 1rem;margin-top:.75rem;border:1px solid var(--line);border-radius:var(--card-radius);background:var(--surface)}h3{margin:0 0 .65rem;font-size:.875rem;font-weight:650}.stage-overview>div{display:flex;gap:.5rem;flex-wrap:wrap}.stage-overview article{padding:.6rem .75rem;border:1px solid var(--line);border-radius:var(--control-radius);background:var(--surface-2);display:grid;gap:.3rem;flex:1;min-width:8rem}.stage-overview span{font-size:.8125rem;color:var(--muted)}.stage-overview strong{font-size:1.2rem;font-weight:600}
 .operations-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,22rem),1fr));gap:.75rem;margin-top:.75rem}.operation-panel{padding:1rem;border:1px solid var(--line);border-radius:var(--card-radius);min-width:0;background:var(--surface)}.operation-panel header{display:flex;justify-content:space-between;gap:.7rem}.operation-panel header span{font-size:.75rem;color:var(--muted)}.operation-panel p{font-size:.8125rem}.task-row{display:flex;justify-content:space-between;align-items:center;gap:.75rem;width:100%;padding:.7rem .2rem;border:0;border-top:1px solid var(--line);background:none;text-align:left;color:var(--text);font:inherit;cursor:pointer}.task-row:hover{background:var(--surface-2)}.task-row strong{font-weight:600;font-size:.875rem;overflow-wrap:anywhere}.task-row small{display:block;color:var(--muted);margin-top:.2rem;font-size:.75rem}.task-action{font-size:.75rem;color:var(--primary-text);max-width:40%;text-align:right;overflow-wrap:anywhere}
</style>
